#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/operator_sfu_owner_endpoint_v3;R=$ROOT/scripts/run_memory_capped.sh;V=$ROOT/work/toolchain/conda/bin/verilator;mkdir -p "$OUT"
S=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/common/rv_fifo.sv" "$ROOT/rtl/sfu/fp32_reduce16.sv" "$ROOT/rtl/sfu/fp32_reduce_max16.sv" "$ROOT/rtl/sfu/fp32_rsqrt_nr2.sv" "$ROOT/rtl/sfu/fp32_reciprocal_nr2.sv" "$ROOT/rtl/sfu/fp32_exp2_pwl_pipe.sv" "$ROOT/rtl/sfu/fp32_norm16_rms_l2_pipe.sv" "$ROOT/rtl/sfu/fp32_group_rmsnorm16_pipe.sv" "$ROOT/rtl/sfu/fp32_rope_pair_pipe.sv" "$ROOT/rtl/sfu/fp32_exp2_pwl_rawpipe.sv" "$ROOT/rtl/attention/fp32_block32_softmax_weights.sv" "$ROOT/rtl/sfu/fp32_mlo_merge_coeff_rawpipe.sv" "$ROOT/rtl/sfu/fp32_mlo_merge_beat_rawpipe.sv" "$ROOT/rtl/sfu/fp32_mlo_summary_merge_stream_rawpipe.sv" "$ROOT/rtl/sfu/fp32_mlo_summary_merge_stream.sv" "$ROOT/rtl/sfu/bf16_silu_mul_lut_lane.sv" "$ROOT/rtl/sfu/bf16_silu_mul_lut_array8_fixed.sv" "$ROOT/rtl/sfu/fp32_pwl_nonlinear_pipe.sv" "$ROOT/rtl/integration/operator_sfu_vector_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_scalar_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_norm_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_rope_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_online_softmax_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_gate_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_pwl_endpoint_v3.sv" "$ROOT/rtl/integration/operator_sfu_owner_endpoint_v3.sv" "$ROOT/tb/tb_operator_sfu_owner_endpoint_v3.sv")
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" timeout --foreground --signal=INT --kill-after=30s 600s "$V" --binary --threads 4 --timing -Wall -I"$ROOT/rtl/sfu" -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -Wno-UNOPTTHREADS -Wno-WIDTH -Wno-SYNCASYNCNET -Wno-PINCONNECTEMPTY -j 4 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_operator_sfu_owner_endpoint_v3 --Mdir "$OUT/obj" -o tb "${S[@]}" >"$OUT/build.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" timeout --foreground --signal=INT --kill-after=30s 600s "$OUT/obj/tb"|tee "$OUT/test.log"
grep -q 'OPERATOR_SFU_OWNER_ENDPOINT_V3_PASS opcodes=23 invalid=1 checked_completions=24' "$OUT/test.log"
